643	# 客户编号可表示的最大值（SQLite INTEGER 上限，2^63 - 1）。
644	# 超过它的整数无法作为编号保存或查询，必须在进入数据库前明确拒绝。
645	MAX_CLIENT_ID = 9223372036854775807
646	
647	# SQLite 单条语句允许的最大绑定参数数量（SQLITE_MAX_VARIABLE_NUMBER）。
648	# 不同版本取值不同（历史上 999、32766，较新版本 250000），因此以运行时
649	# 查询为准；批量修改一次选择的客户数可能超过它，不能把全部编号塞进单条
650	# 语句的 IN(?,…)，必须分块执行。
651	DEFAULT_SQL_VARIABLE_LIMIT = 999
652	COMPILE_OPTION_PREFIX = "MAX_VARIABLE_NUMBER="
653	
654	
655	def sql_variable_limit(database):
656	    """返回运行时 SQLite 单条语句可绑定的最大参数数量。
657	
658	    取自编译选项 MAX_VARIABLE_NUMBER（各 SQLite 版本默认值不同：999、32766、
659	    250000）；取不到时回退到保守的历史默认值 999。
660	    """
661	    try:
662	        for (option,) in database.execute("PRAGMA compile_options"):
663	            if option.startswith(COMPILE_OPTION_PREFIX):
664	                limit = int(option[len(COMPILE_OPTION_PREFIX):])
665	                if limit > 0:
666	                    return limit
667	    except (sqlite3.DatabaseError, ValueError):
668	        pass
669	    return DEFAULT_SQL_VARIABLE_LIMIT
