679	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
680	
681	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
682	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
683	    """
684	    if not isinstance(value, str):
685	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
686	    text = value.strip()
687	    if not text:
688	        return None
689	    if field_name == "important_date":
690	        ok, reason = check_date(text)
