696	def batch_update_clients(database, payload):
697	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
698	
699	    任一问题都整次拒绝，不写入任何客户。
700	    """
701	    if not isinstance(payload, dict):
702	        raise BatchUpdateError("请求体必须是 JSON 对象")
703	
704	    raw_ids = payload.get("ids")
705	    if not isinstance(raw_ids, list):
706	        raise BatchUpdateError("ids 必须是客户编号数组")
707	    if not raw_ids:
708	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
709	
710	    ids = []
711	    seen_ids = set()
712	    for raw_id in raw_ids:
713	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
714	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
715	        if raw_id > MAX_CLIENT_ID:
716	            raise BatchUpdateError(
717	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
718	                % (raw_id, MAX_CLIENT_ID))
719	        if raw_id not in seen_ids:
720	            seen_ids.add(raw_id)
721	            ids.append(raw_id)
722	
723	    raw_updates = payload.get("updates", {})
724	    if not isinstance(raw_updates, dict):
725	        raise BatchUpdateError("updates 必须是字段修改说明对象")
726	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
727	    if extra:
728	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
729	
730	    actions = {}
731	    for field_name in OPTIONAL_FIELDS:
732	        spec = raw_updates.get(field_name, {"op": "keep"})
733	        if not isinstance(spec, dict):
734	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
735	        op = spec.get("op")
736	        if op not in ("keep", "set", "clear"):
737	            raise BatchUpdateError(
738	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
739	        if op == "keep":
740	            continue
741	        if op == "clear":
742	            actions[field_name] = None
743	        else:
744	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
745	
746	    if not actions:
747	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
748	
749	    # 一次选择的客户数可能超过 SQLite 单条语句的参数上限，存在性检查与 UPDATE
750	    # 都按参数上限分块；UPDATE 的多个分块在同一事务内一次提交，整笔修改要么
751	    # 全部生效要么全部不生效，不会因分块变成多次部分修改。
752	    variable_limit = sql_variable_limit(database)
753	
754	    existing = set()
755	    for id_chunk in _chunked(ids, variable_limit):
756	        placeholders = ",".join("?" for _ in id_chunk)
757	        existing.update(
758	            row[0]
759	            for row in database.execute(
760	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
761	            )
762	        )
763	    missing = [cid for cid in ids if cid not in existing]
764	    if missing:
765	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
766	
767	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
768	    id_chunk_size = max(1, variable_limit - len(actions))
769	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
770	    values = list(actions.values())
771	    try:
772	        for id_chunk in _chunked(ids, id_chunk_size):
773	            placeholders = ",".join("?" for _ in id_chunk)
774	            database.execute(
775	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
776	                values + id_chunk,
777	            )
778	        database.commit()
779	    except sqlite3.DatabaseError:
780	        database.rollback()
781	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
782	
783	    return {"updated_count": len(ids)}
