786	def parse_csv(text):
787	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
788	
789	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
790	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
791	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
792	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
793	    - 文件结束时仍有字段处于引号内（引号未闭合）。
794	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
795	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
796	    """
797	    rows = []
798	    record = []
799	    field = []
800	    quoted = False        # 当前字段处于引号内
801	    started = False       # 当前字段已经开始（已有内容或已进入引号）
802	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
803	    record_number = 0     # 0 = 表头，1 起为数据记录
804	    i = 0
805	    n = len(text)
806	
807	    def location():
808	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
809	
810	    def structure_error(kind):
811	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
812	
813	    def finish_record():
814	        nonlocal record, field, started, closed
815	        record.append("".join(field))
816	        rows.append(record)
817	        record = []
818	        field = []
819	        started = False
820	        closed = False
821	
822	    while i < n:
823	        c = text[i]
824	        if quoted:
825	            if c == '"':
826	                if i + 1 < n and text[i + 1] == '"':
827	                    field.append('"')
828	                    i += 2
829	                    continue
830	                quoted = False
831	                closed = True
832	                i += 1
833	                continue
834	            if c == "\r":
835	                # 统一字段内换行符为 LF
836	                if i + 1 < n and text[i + 1] == "\n":
837	                    i += 1
838	                field.append("\n")
839	                i += 1
840	                continue
841	            field.append(c)
842	            i += 1
843	            continue
844	        if closed:
845	            # 引号已结束，只允许逗号、记录换行或文件结束
846	            if c == ",":
847	                record.append("".join(field))
848	                field = []
849	                started = False
850	                closed = False
851	            elif c in "\r\n":
852	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
853	                    i += 1
854	                finish_record()
855	                record_number += 1
856	            else:
857	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
858	            i += 1
859	            continue
860	        if c == '"' and not started:
861	            quoted = True
862	            started = True
863	        elif c == '"':
864	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
865	        elif c == ",":
866	            record.append("".join(field))
867	            field = []
868	            started = False
869	        elif c in "\r\n":
870	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
871	                i += 1
872	            if not started and not record and not field:
873	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
874	                i += 1
875	                continue
876	            finish_record()
877	            record_number += 1
878	        else:
879	            field.append(c)
880	            started = True
881	        i += 1
882	    if quoted:
883	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
884	    if started or field or record or closed:
885	        record.append("".join(field))
886	        rows.append(record)
887	    if not rows:
888	        raise FileError("CSV 内容为空：缺少表头")
889	    return rows[0], rows[1:]
