891	
892	def check_date(value):
893	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
894	    match = DATE_RE.match(value)
895	    if not match:
896	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
897	    try:
898	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
899	    except ValueError:
900	        return False, "重要日期无效（%s）：不是真实日历日期" % value
901	    return True, None
902	
903	
904	def import_clients(database, text):
905	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
906	    header, data_rows = parse_csv(text)
907	    headers = [h.strip() for h in header]
908	
909	    seen = set()
910	    duplicates = []
911	    for h in headers:
912	        if h in seen and h not in duplicates:
913	            duplicates.append(h)
914	        seen.add(h)
915	    if duplicates:
916	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
917	    unknown = [h for h in headers if h not in ALL_COLUMNS]
918	    if unknown:
919	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
920	    if "name" not in headers:
921	        raise FileError("缺少名称列：表头必须包含 name 列")
922	
923	    index = {h: i for i, h in enumerate(headers)}
924	    name_index = index["name"]
925	    date_index = index.get("important_date")
926	
927	    existing = {}
928	    for cid, cname in database.execute("SELECT id, name FROM clients"):
929	        existing[(cname or "").strip().casefold()] = cid
930	
931	    imported = []
932	    failures = []
933	    seen_in_file = {}
934	
935	    for row_number, raw in enumerate(data_rows, start=1):
936	        if len(raw) != len(headers):
937	            failures.append({
938	                "row": row_number,
939	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
940	            })
941	            continue
942	
943	        name = raw[name_index].strip()
944	        problems = []
945	        if not name:
946	            problems.append("缺少名称：name 列为空")
947	        date_value = ""
948	        if date_index is not None:
949	            date_value = raw[date_index].strip()
950	            if date_value:
951	                ok, reason = check_date(date_value)
952	                if not ok:
953	                    problems.append(reason)
954	        if problems:
955	            failures.append({"row": row_number, "reason": "；".join(problems)})
956	            continue
957	
958	        key = name.casefold()
959	        if key in existing:
960	            failures.append({
961	                "row": row_number,
962	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
963	            })
964	            continue
965	        if key in seen_in_file:
966	            failures.append({
967	                "row": row_number,
968	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
969	            })
970	            continue
971	
972	        seen_in_file[key] = row_number
973	        record = {"name": name}
974	        for field_name in OPTIONAL_FIELDS:
975	            idx = index.get(field_name)
976	            value = raw[idx].strip() if idx is not None else ""
977	            record[field_name] = value or None
978	        imported.append((row_number, record))
979	
980	    # 全部有效新客户在同一事务内逐条写入并在最后一次提交：只要保存已经开始
981	    # （已有一条 INSERT 执行），无论后续某条写入失败还是最终提交失败，都回滚
982	    # 整笔事务——本次文件中的任何新客户都不保留，原有客户资料保持原样，
983	    # 并以明确的保存失败错误拒绝整次导入，不返回任何新增数量。
984	    saved = []
985	    try:
986	        for row_number, record in imported:
987	            cursor = database.execute(
988	                "INSERT INTO clients (name, source, region, industry, important_date)"
989	                " VALUES (:name, :source, :region, :industry, :important_date)",
990	                record,
991	            )
992	            saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
993	        database.commit()
994	    except sqlite3.DatabaseError:
995	        database.rollback()
996	        raise ImportSaveError("保存失败：数据库写入出错，本次导入已全部撤销，没有新增任何客户")
997	
998	    return {
999	        "imported_count": len(saved),
1000	        "failed_count": len(failures),
1001	        "imported": saved,
1002	        "failures": failures,
1003	    }
1004	
1005	
1006	def main():
1007	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
1008	    commands = parser.add_subparsers(dest="command", required=True)
1009	    serve = commands.add_parser("serve", help="Start the HTTP service")
1010	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
1011	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
1012	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
1013	    args = parser.parse_args()
1014	    if not 0 <= args.port <= 65535:
1015	        parser.error("port must be between 0 and 65535")
1016	    args.data_dir.mkdir(parents=True, exist_ok=True)
1017	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
1018	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
1019	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
1020	    for field_name in OPTIONAL_FIELDS:
1021	        if field_name not in columns:
1022	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
1023	    database.commit()
1024	
1025	    class Handler(BaseHTTPRequestHandler):
1026	        def respond(self, status, value, *, html=False, allow=None):
1027	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
1028	            self.send_response(status)
1029	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
1030	            self.send_header("Content-Length", str(len(payload)))
1031	            if status == 405:
