1059	                database.rollback()
1060	                self.respond(400, {"error": str(exc)})
1061	                return
1062	            self.respond(200, result)
1063	
1064	        def handle_batch_update(self):
1065	            try:
1066	                length = int(self.headers.get("Content-Length") or 0)
1067	            except ValueError:
1068	                length = 0
1069	            if length > MAX_BODY:
1070	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
