97	async function stopApp(ctx) {
98	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
99	  const timer = setTimeout(() => {
100	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
101	  }, 2000);
102	  await new Promise(r => ctx.proc.on("exit", r));
103	  clearTimeout(timer);
104	}
