import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, mkdirSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const TMP = mkdtempSync(join(tmpdir(), "clientbook-guard-"));
let fails = 0;
const check = (label, cond, extra="") => {
  console.log((cond ? "PASS " : "FAIL ") + label + (extra ? `  ${extra}` : ""));
  if (!cond) fails++;
};
const csvField = v => `"${String(v).replace(/"/g, '""')}"`;
const buildCsv = (header, rows) => header.map(csvField).join(",") + "\n" +
  rows.map(r => r.map(csvField).join(",")).join("\n") + "\n";

async function main() {
  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, "data")], {cwd: HERE, stdio: ["ignore","pipe","pipe"]});
  const port = await new Promise((resolve, reject) => {
    let buf = "";
    proc.stdout.on("data", d => { buf += d; const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/); if (m) resolve(Number(m[1])); });
    proc.on("exit", c => reject(new Error("app exited " + c)));
  });
  const base = `http://127.0.0.1:${port}`;
  for (let i = 0; i < 80; i++) { try { if ((await fetch(base+"/health")).status===200) break; } catch {} await new Promise(r=>setTimeout(r,100)); }

  const browser = await puppeteer.launch({executablePath: process.env.CHROME || "/usr/bin/google-chrome",
    headless: true, args: ["--no-sandbox","--disable-dev-shm-usage"]});

  const openHeldPage = async () => {
    const page = await browser.newPage();
    const held = [];
    let posts = 0;
    await page.setRequestInterception(true);
    page.on("request", req => {
      if (req.method()==="POST" && req.url().endsWith("/api/clients/import")) { posts++; held.push(req); return; }
      req.continue();
    });
    await page.setCacheEnabled(false);
    await page.goto(base+"/", {waitUntil: "networkidle0"});
    const upload = async (name, content) => {
      const dir = join(TMP, "up"); mkdirSync(dir, {recursive: true});
      const p = join(dir, name); writeFileSync(p, content, "utf8");
      const input = await page.$("#file-input");
      await input.uploadFile(p);
      await page.waitForFunction(n => document.getElementById("filename").textContent === n, {}, name);
    };
    const waitHeld = async n => {
      const d = Date.now() + 5000;
      while (Date.now() < d) { if (held.length === n) return; await new Promise(r=>setTimeout(r,25)); }
      throw new Error("held != " + n);
    };
    const snap = () => page.evaluate(() => ({
      btn: document.getElementById("submit-btn").textContent,
      disabled: document.getElementById("submit-btn").disabled,
      banners: [...document.querySelectorAll("#report .banner")].map(b => b.className),
      text: document.getElementById("report").innerText.replace(/\s+/g," ").trim(),
      fileCount: document.getElementById("file-input").files.length,
      filename: document.getElementById("filename").textContent,
      rows: [...document.querySelectorAll("#clients-body tr")].map(tr => tr.children[2].textContent.trim()),
    }));
    return {page, held, upload, waitHeld, snap, posts: () => posts};
  };

  try {
    // ===== 场景 1：等待中更换文件（不取消）→ 回复只算第一份；结束后保留第二份，
    //       再次主动提交使用第二份；之后原文件仍可再导入（重复跳过） =====
    {
      const s = await openHeldPage();
      // 无文件提交：只提示不发请求（派发 submit 事件绕过原生 required 气泡）
      await s.page.evaluate(() =>
        document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
      await new Promise(r=>setTimeout(r,100));
      let sn = await s.snap();
      check("无文件提交：提示先选择 CSV、不发请求、按钮仍为导入可用",
        sn.text.includes("请先选择 CSV") && s.posts() === 0 && sn.btn === "导入" && !sn.disabled, sn.text);

      await s.upload("first.csv", buildCsv(["name"], [["第一份客户甲"], ["第一份客户乙"]]));
      s.page.click("#submit-btn");
      await s.waitHeld(1);
      await new Promise(r=>setTimeout(r,100));
      sn = await s.snap();
      check("等待中：按钮「正在导入…」禁用、仅 busy 提示",
        sn.btn === "正在导入…" && sn.disabled && sn.banners.length === 1 &&
        sn.banners[0].includes("busy") && sn.text.includes("正在导入"), JSON.stringify(sn));

      // 重复提交：点击、requestSubmit、原始 submit 事件、回车
      await s.page.evaluate(() => {
        const f = document.getElementById("import-form");
        f.requestSubmit();
        f.dispatchEvent(new Event("submit", {cancelable: true}));
      });
      await s.page.click("#submit-btn").catch(() => {});
      await s.page.keyboard.press("Enter").catch(() => {});
      await new Promise(r=>setTimeout(r,300));
      check("等待中重复提交：仅 1 个挂起请求", s.posts() === 1 && s.held.length === 1, `posts=${s.posts()}`);
      sn = await s.snap();
      check("等待中重复提交：仍是 busy，未变成成功/失败/未选文件",
        sn.btn === "正在导入…" && sn.banners.length === 1 && sn.banners[0].includes("busy"), sn.text);

      // 等待中换选第二份文件
      await s.upload("second.csv", buildCsv(["name"], [["第二份客户丙"]]));
      sn = await s.snap();
      check("等待中换文件不解除等待", sn.btn === "正在导入…" && sn.disabled &&
        sn.filename === "second.csv" && sn.fileCount === 1, JSON.stringify({btn: sn.btn, f: sn.filename}));

      // 放行：后端处理的是第一份
      s.held.shift().continue();
      await s.page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
        !document.getElementById("submit-btn").disabled, {timeout: 5000});
      await new Promise(r=>setTimeout(r,150));
      sn = await s.snap();
      check("回复只说明第一份文件（新增 2 条），不含第二份客户",
        /新增\s*2\s*条，未导入\s*0\s*条/.test(sn.text) &&
        sn.rows.includes("第一份客户甲") && sn.rows.includes("第一份客户乙") &&
        !sn.rows.includes("第二份客户丙"), sn.text);
      check("结束后保留等待期间改选的第二份文件，不恢复最初文件",
        sn.fileCount === 1 && sn.filename === "second.csv", JSON.stringify({c: sn.fileCount, f: sn.filename}));
      check("全程仅 1 次请求（不自动补交第二份）", s.posts() === 1, `posts=${s.posts()}`);

      // 用户主动再次提交：使用当前选中的第二份
      await s.page.evaluate(() =>
        document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
      await s.waitHeld(2);
      s.held.shift().continue();
      await s.page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
        !document.getElementById("submit-btn").disabled, {timeout: 5000});
      await new Promise(r=>setTimeout(r,150));
      sn = await s.snap();
      check("主动提交使用当前的第二份文件：新增 1 条第二份客户丙，共 3 名",
        /新增\s*1\s*条，未导入\s*0\s*条/.test(sn.text) && sn.rows.includes("第二份客户丙") &&
        sn.rows.length === 3, sn.text);
      check("共 2 次请求", s.posts() === 2, `posts=${s.posts()}`);

      // 再导入第一份：允许，重复按现有规则跳过
      await s.upload("first.csv", buildCsv(["name"], [["第一份客户甲"], ["第一份客户乙"]]));
      await s.page.evaluate(() =>
        document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
      await s.waitHeld(3);
      s.held.shift().continue();
      await s.page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
        !document.getElementById("submit-btn").disabled, {timeout: 5000});
      await new Promise(r=>setTimeout(r,150));
      sn = await s.snap();
      check("上一轮结束后原文件可再次导入：0 新增、2 未导入（重复跳过），仍 3 名",
        /新增\s*0\s*条，未导入\s*2\s*条/.test(sn.text) && sn.rows.length === 3, sn.text);
      check("共 3 次请求（等待限制不是永久禁止）", s.posts() === 3, `posts=${s.posts()}`);
      await s.page.close();
    }

    // ===== 场景 2：等待中取消选择 → 结束后保持未选；再提交只提示先选择、不发请求 =====
    {
      const s = await openHeldPage();
      await s.upload("cancel.csv", buildCsv(["name"], [["取消场景客户"]]));
      s.page.click("#submit-btn");
      await s.waitHeld(1);
      await new Promise(r=>setTimeout(r,100));

      // 等待中取消选择（模拟用户在文件选择框点清除）
      await s.page.evaluate(() => {
        const inp = document.getElementById("file-input");
        Object.defineProperty(inp, "files", {value: new DataTransfer().files, configurable: true});
        inp.dispatchEvent(new Event("change", {bubbles: true}));
      });
      let sn = await s.snap();
      check("等待中取消选择：输入框空、仍在等待",
        sn.fileCount === 0 && sn.filename === "" && sn.btn === "正在导入…" && sn.disabled,
        JSON.stringify({c: sn.fileCount, btn: sn.btn}));

      // 重复提交（此时无文件）也不能替换提示或发请求
      await s.page.evaluate(() =>
        document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
      await new Promise(r=>setTimeout(r,200));
      check("等待中无文件状态下重复提交：不发新请求、仍是 busy",
        s.posts() === 1 && s.held.length === 1, `posts=${s.posts()}`);
      sn = await s.snap();
      check("busy 未被换成「请先选择 CSV」",
        sn.banners.length === 1 && sn.banners[0].includes("busy") && !sn.text.includes("请先选择"), sn.text);

      s.held.shift().continue();
      await s.page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
        !document.getElementById("submit-btn").disabled, {timeout: 5000});
      await new Promise(r=>setTimeout(r,150));
      sn = await s.snap();
      check("结束后：结果说明已提交文件（新增 1 条），选择保持未选",
        /新增\s*1\s*条，未导入\s*0\s*条/.test(sn.text) && sn.fileCount === 0 && sn.filename === "", sn.text);
      check("全程仅 1 次请求", s.posts() === 1, `posts=${s.posts()}`);

      // 再提交：只提示、不发请求
      await s.page.evaluate(() =>
        document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
      await new Promise(r=>setTimeout(r,200));
      sn = await s.snap();
      check("结束后无文件提交：提示先选择 CSV、不发请求、按钮可用",
        sn.text.includes("请先选择 CSV") && s.posts() === 1 && sn.btn === "导入" && !sn.disabled, sn.text);
      await s.page.close();
    }
  } finally {
    await browser.close();
    proc.kill();
    await new Promise(r => proc.on("exit", r));
    rmSync(TMP, {recursive: true, force: true});
  }
  console.log(fails ? "FAILURES" : "DONE");
  process.exit(fails ? 1 : 0);
}

main().catch(err => { console.error(err); process.exit(1); });

