import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, mkdirSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const TMP = mkdtempSync(join(tmpdir(), "clientbook-guard-"));
let fails = 0;
const check = (label, cond, extra="") => {
  console.log((cond ? "PASS " : "FAIL ") + label + (extra ? `  ${extra}` : ""));
  if (!cond) fails++;
};
const csvField = v => `"${String(v).replace(/"/g, '""')}"`;
const buildCsv = (header, rows) => header.map(csvField).join(",") + "\n" +
  rows.map(r => r.map(csvField).join(",")).join("\n") + "\n";

async function main() {
  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, "data")], {cwd: HERE, stdio: ["ignore","pipe","pipe"]});
  const port = await new Promise((resolve, reject) => {
    let buf = "";
    proc.stdout.on("data", d => { buf += d; const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/); if (m) resolve(Number(m[1])); });
    proc.on("exit", c => reject(new Error("app exited " + c)));
  });
  const base = `http://127.0.0.1:${port}`;
  for (let i = 0; i < 80; i++) { try { if ((await fetch(base+"/health")).status===200) break; } catch {} await new Promise(r=>setTimeout(r,100)); }

  const browser = await puppeteer.launch({executablePath: process.env.CHROME || "/usr/bin/google-chrome",
    headless: true, args: ["--no-sandbox","--disable-dev-shm-usage"]});
  try {
    const page = await browser.newPage();
    const held = [];
    await page.setRequestInterception(true);
    let posts = 0;
    page.on("request", req => {
      if (req.method()==="POST" && req.url().endsWith("/api/clients/import")) {
        posts++;
        held.push(req);
        return; // hold
      }
      req.continue();
    });
    await page.setCacheEnabled(false);
    await page.goto(base+"/", {waitUntil: "networkidle0"});

    const upload = async (name, content) => {
      const dir = join(TMP, "up"); mkdirSync(dir, {recursive: true});
      const p = join(dir, name); writeFileSync(p, content, "utf8");
      const input = await page.$("#file-input");
      await input.uploadFile(p);
      await page.waitForFunction(n => document.getElementById("filename").textContent === n, {}, name);
    };
    const clearFile = () => page.evaluate(() => {
      const inp = document.getElementById("file-input");
      Object.defineProperty(inp, "files", {value: new DataTransfer().files, configurable: true});
      inp.dispatchEvent(new Event("change", {bubbles: true}));
    });

    // --- no-file submit: prompt only, no request, button stays "导入" enabled ---
    // 原生 required 校验会拦截 requestSubmit；页面内提示由 submit 监听处理，
    // 与 page_test.mjs 一样直接派发 submit 事件触达。
    await page.evaluate(() =>
      document.getElementById("import-form").dispatchEvent(new Event("submit", {cancelable: true})));
    await new Promise(r=>setTimeout(r,100));
    let snap = await page.evaluate(() => ({
      text: document.getElementById("report").innerText.trim(),
      btn: document.getElementById("submit-btn").textContent,
      disabled: document.getElementById("submit-btn").disabled,
    }));
    check("无文件提交：提示先选择 CSV、不发请求、按钮仍为导入可用",
      snap.text.includes("请先选择 CSV") && posts === 0 && snap.btn === "导入" && !snap.disabled, snap.text);

    const waitHeld = async n => {
      const deadline = Date.now() + 5000;
      while (Date.now() < deadline) { if (held.length === n) return; await new Promise(r=>setTimeout(r,25)); }
      throw new Error("held count not " + n + " (actual " + held.length + ", posts " + posts + ")");
    };

    // --- submit first file; request held ---
    await upload("first.csv", buildCsv(["name"], [["第一份客户甲"], ["第一份客户乙"]]));
    page.click("#submit-btn");
    await waitHeld(1);
    await new Promise(r=>setTimeout(r,100));
    await new Promise(r=>setTimeout(r,100));
    snap = await page.evaluate(() => ({
      btn: document.getElementById("submit-btn").textContent,
      disabled: document.getElementById("submit-btn").disabled,
      banners: [...document.querySelectorAll("#report .banner")].map(b => b.className),
      text: document.getElementById("report").innerText.replace(/\s+/g," ").trim(),
    }));
    check("等待中：按钮显示「正在导入…」且禁用、仅一条 busy 提示",
      snap.btn === "正在导入…" && snap.disabled && snap.banners.length === 1 &&
      snap.banners[0].includes("busy") && snap.text.includes("正在导入"), JSON.stringify(snap));

    // resubmit while held: click, requestSubmit(), raw submit event, Enter
    await page.evaluate(() => {
      const form = document.getElementById("import-form");
      form.requestSubmit();
      form.dispatchEvent(new Event("submit", {cancelable: true}));
    });
    await page.click("#submit-btn").catch(() => {});
    await page.keyboard.press("Enter").catch(() => {});
    await new Promise(r=>setTimeout(r,300));
    check("等待中重复提交：只有 1 个挂起请求", posts === 1 && held.length === 1, `posts=${posts} held=${held.length}`);
    snap = await page.evaluate(() => ({
      btn: document.getElementById("submit-btn").textContent,
      banners: [...document.querySelectorAll("#report .banner")].map(b => b.className),
      text: document.getElementById("report").innerText.trim(),
    }));
    check("等待中重复提交：仍是正在导入提示，未变成成功/失败/未选文件",
      snap.btn === "正在导入…" && snap.banners.length === 1 &&
      snap.banners[0].includes("busy") && snap.text.includes("正在导入"), snap.text);

    // change file mid-flight then cancel
    await upload("second.csv", buildCsv(["name"], [["第二份客户丙"]]));
    await clearFile();
    snap = await page.evaluate(() => ({
      filename: document.getElementById("filename").textContent,
      fileCount: document.getElementById("file-input").files.length,
      btn: document.getElementById("submit-btn").textContent,
      busy: !!document.querySelector("#report .banner.busy"),
      tableVisible: getComputedStyle(document.getElementById("clients-table")).display,
    }));
    check("等待期间可更换并取消选择：输入框为空、仍在等待、表格仍可见",
      snap.filename === "" && snap.fileCount === 0 && snap.btn === "正在导入…" && snap.busy,
      JSON.stringify(snap));

    // release held request: backend processes FIRST file
    held.shift().continue();
    await page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
      !document.getElementById("submit-btn").disabled, {timeout: 5000});
    await new Promise(r=>setTimeout(r,150));
    snap = await page.evaluate(() => ({
      text: document.getElementById("report").innerText.replace(/\s+/g," ").trim(),
      fileCount: document.getElementById("file-input").files.length,
      rows: [...document.querySelectorAll("#clients-body tr")].map(tr => tr.children[2].textContent.trim()),
    }));
    check("结果只说明提交时的第一份文件（新增 2 条、两行都在）",
      /新增\s*2\s*条，未导入\s*0\s*条/.test(snap.text) &&
      snap.rows.includes("第一份客户甲") && snap.rows.includes("第一份客户乙"), snap.text);
    check("回复不把后来选过的第二份文件算进来", !snap.rows.includes("第二份客户丙"), snap.text);
    check("处理结束：取消选择保持未选，不恢复最初文件", snap.fileCount === 0, String(snap.fileCount));
    check("全程只有 1 次导入请求（无自动补交）", posts === 1, `posts=${posts}`);

    // --- after completion, re-import same file: allowed; duplicates skipped by existing rules ---
    await upload("first.csv", buildCsv(["name"], [["第一份客户甲"], ["第一份客户乙"]]));
    await page.evaluate(() => document.getElementById("import-form").requestSubmit());
    await page.waitForFunction(() => document.getElementById("submit-btn").textContent === "导入" &&
      !document.getElementById("submit-btn").disabled);
    await new Promise(r=>setTimeout(r,150));
    snap = await page.evaluate(() => ({
      text: document.getElementById("report").innerText.replace(/\s+/g," ").trim(),
      rows: document.querySelectorAll("#clients-body tr").length,
      fileCount: document.getElementById("file-input").files.length,
    }));
    check("结束后可再次主动导入原文件：0 新增、2 未导入（重复跳过），客户仍 2 名，文件保留",
      /新增\s*0\s*条，未导入\s*2\s*条/.test(snap.text) && snap.rows === 2 && snap.fileCount === 1, snap.text);
    check("两次主动提交共 2 次请求", posts === 2, `posts=${posts}`);
  } finally {
    await browser.close();
    proc.kill();
    await new Promise(r => proc.on("exit", r));
    rmSync(TMP, {recursive: true, force: true});
  }
  console.log(fails ? "FAILURES" : "DONE");
  process.exit(fails ? 1 : 0);
}

main().catch(err => { console.error(err); process.exit(1); });

